import {wavesFor} from './data/waves.js';
import {spawnEnemy} from './enemies.js';
export function initWaves(g){g.waveList=wavesFor(g.level,g.levelIndex);g.wave=0;g.queue=[];g.spawnClock=0;g.intermission=0;g.waveActive=false;}
export function callWave(g){if(g.paused||g.outcome||g.wave>=g.waveList.length)return false;if(g.wave>0&&g.intermission<=0)return false;const bonus=g.wave===0?0:Math.ceil(g.intermission*.8);g.gold+=bonus;g.hero.q=Math.max(0,g.hero.q-bonus*.3);g.hero.w=Math.max(0,g.hero.w-bonus*.3);g.queue=g.waveList[g.wave].flatMap(group=>Array.from({length:group.count},()=>({type:group.type,gap:group.gap})));g.wave++;g.intermission=0;g.waveActive=true;g.spawnClock=0;g.audio.play('horn');g.notify(bonus?`Wave ${g.wave} · +${bonus} early-call gold`:`Wave ${g.wave} approaches`);return true;}
export function updateWaves(g,dt){if(g.queue.length){g.spawnClock-=dt;while(g.spawnClock<=0&&g.queue.length){const item=g.queue.shift();spawnEnemy(g,item.type);g.spawnClock+=item.gap;}}if(g.waveActive&&!g.queue.length&&!g.enemies.length){g.waveActive=false;if(g.wave>=g.waveList.length){g.finish(true);return;}g.gold+=25+g.wave*5+g.levelIndex*4;g.intermission=20;g.notify('Road cleared · prepare your defenses');}if(g.intermission>0){g.intermission=Math.max(.001,g.intermission-dt);if(g.intermission<=.001)callWave(g);}}
